 65	// vendor copies a generated grammar from repoRoot/subdir into destDir:
 66	// src/parser.c, src/scanner.c when present, src/*.h, src/tree_sitter/*.h and the
 67	// license file as LICENSE (from the grammar directory, else the repository root). Files
 68	// of those kinds already in destDir that the new grammar lacks are removed;
 69	// everything else there, such as binding.go, is left alone. Nothing in destDir
 70	// changes unless the grammar has a parser.c the go-tree-sitter runtime can load.
 71	func vendor(repoRoot, subdir, destDir string) ([]string, int, error) {
 72		grammarRoot := filepath.Join(repoRoot, subdir)
 73		parserC, err := os.ReadFile(filepath.Join(grammarRoot, "src", "parser.c"))
 74		if err != nil {
 75			return nil, 0, fmt.Errorf("no generated %s (pick a ref that ships generated sources)", filepath.ToSlash(filepath.Join(subdir, "src", "parser.c")))
 76		}
 77		abi, err := languageABI(parserC)
 78		if err != nil {
 79			return nil, 0, err
 80		}
 81		if abi < minABI || abi > maxABI {
 82			return nil, 0, abiError{abi}
 83		}
 84	
 85		sources := map[string]string{"parser.c": filepath.Join(grammarRoot, "src", "parser.c")}
 86		if scanner := filepath.Join(grammarRoot, "src", "scanner.c"); fileExists(scanner) {
 87			sources["scanner.c"] = scanner
 88		}
 89		for _, dir := range []string{"", "tree_sitter/"} {
 90			headers, err := filepath.Glob(filepath.Join(grammarRoot, "src", filepath.FromSlash(dir), "*.h"))
 91			if err != nil {
 92				return nil, 0, err
 93			}
 94			for _, h := range headers {
 95				sources[dir+filepath.Base(h)] = h
 96			}
 97		}
 98		license := findLicense(grammarRoot)
 99		if license == "" {
100			license = findLicense(repoRoot)
101		}
102		if license == "" {
103			return nil, 0, fmt.Errorf("no LICENSE or COPYING file in %s or the repository root", grammarRoot)
104		}
105		// Always LICENSE: scripts/gen-notices.sh only attributes files by that name.
106		sources["LICENSE"] = license
107	
108		stale, err := vendoredFiles(destDir)
109		if err != nil {
110			return nil, 0, err
111		}
112		for _, rel := range stale {
113			if _, keep := sources[rel]; !keep {
114				if err := os.Remove(filepath.Join(destDir, filepath.FromSlash(rel))); err != nil {
115					return nil, 0, err
116				}
117			}
118		}
119		files := make([]string, 0, len(sources))
120		for rel, src := range sources {
121			data, err := os.ReadFile(src)
122			if err != nil {
123				return nil, 0, err
124			}
125			dst := filepath.Join(destDir, filepath.FromSlash(rel))
126			if err := os.MkdirAll(filepath.Dir(dst), 0o755); err != nil {
127				return nil, 0, err
128			}
129			if err := os.WriteFile(dst, data, 0o644); err != nil {
130				return nil, 0, err
131			}
132			files = append(files, rel)
133		}
134		sort.Strings(files)
135		return files, abi, nil
136	}
