202	func saveManifest(path string, grammars []Grammar) error {
203		var buf bytes.Buffer
204		enc := json.NewEncoder(&buf)
205		enc.SetEscapeHTML(false)
206		enc.SetIndent("", "  ")
207		if err := enc.Encode(grammars); err != nil {
208			return err
209		}
210		return os.WriteFile(path, buf.Bytes(), 0o644)
211	}
