    15	// The ABI range the go-tree-sitter runtime loads. maxABI is also what
    16	// grammars are generated for. TestABIRangeMatchesRuntime fails when a
    17	// go-tree-sitter upgrade changes the range, so this is the one place to edit.
    18	const (
    19		minABI = 13
    20		maxABI = 14
    21	)
    22	
    23	// Grammar is one vendored grammar's origin, as recorded in grammars.json.
    24	type Grammar struct {
    25		Language  string   `json:"language"`
    26		URL       string   `json:"url"`
    27		Reference string   `json:"reference"`
    28		Revision  string   `json:"revision"`
    29		Path      string   `json:"path,omitempty"`
    30		Files     []string `json:"files"`
    31		ABI       int      `json:"abi"`
    32		// LocalChanges marks vendored files that differ from upstream at Revision
    33		// in ways a refresh would discard. Note says how to reapply them.
    34		LocalChanges bool        `json:"local_changes,omitempty"`
    35		Note         string      `json:"note,omitempty"`
    36		LocalBuild   *LocalBuild `json:"local_build,omitempty"`
    37	}
    38	
    39	// LocalBuild is how grammar-refresh turns the upstream checkout into the
    40	// vendored files: Patch (relative to the grammars directory) is applied
    41	// first, then the parser is regenerated when TreeSitterCLI is set.
    42	type LocalBuild struct {
    43		Patch         string   `json:"patch,omitempty"`
    44		TreeSitterCLI string   `json:"tree_sitter_cli,omitempty"`
    45		GenerateArgs  []string `json:"generate_args,omitempty"`
    46	}
