   138	func fileExists(path string) bool {
   139		info, err := os.Stat(path)
   140		return err == nil && !info.IsDir()
   141	}
   142	
   143	func findLicense(dir string) string {
   144		entries, err := os.ReadDir(dir)
   145		if err != nil {
   146			return ""
   147		}
   148		for _, e := range entries {
   149			name := strings.ToUpper(e.Name())
   150			if !e.IsDir() && (strings.HasPrefix(name, "LICENSE") || strings.HasPrefix(name, "COPYING")) {
   151				return filepath.Join(dir, e.Name())
   152			}
   153		}
   154		return ""
   155	}
   156	
   157	// vendoredFiles lists the files in destDir that vendor manages.
   158	func vendoredFiles(destDir string) ([]string, error) {
   159		var out []string
   160		entries, err := os.ReadDir(destDir)
   161		if err != nil {
   162			if os.IsNotExist(err) {
   163				return nil, nil
   164			}
   165			return nil, err
   166		}
   167		for _, e := range entries {
   168			name := e.Name()
   169			upper := strings.ToUpper(name)
   170			switch {
   171			case e.IsDir() && name == "tree_sitter":
   172				headers, err := filepath.Glob(filepath.Join(destDir, "tree_sitter", "*.h"))
   173				if err != nil {
   174					return nil, err
   175				}
   176				for _, h := range headers {
   177					out = append(out, "tree_sitter/"+filepath.Base(h))
   178				}
   179			case name == "parser.c" || name == "scanner.c", !e.IsDir() && strings.HasSuffix(name, ".h"),
   180				strings.HasPrefix(upper, "LICENSE"), strings.HasPrefix(upper, "COPYING"):
   181				out = append(out, name)
   182			}
   183		}
   184		return out, nil
   185	}
   186	
   187	func loadManifest(path string) ([]Grammar, error) {
   188		data, err := os.ReadFile(path)
   189		if err != nil {
   190			if os.IsNotExist(err) {
   191				return nil, nil
   192			}
   193			return nil, err
   194		}
   195		var grammars []Grammar
   196		if err := json.Unmarshal(data, &grammars); err != nil {
   197			return nil, fmt.Errorf("%s: %w", path, err)
   198		}
   199		return grammars, nil
   200	}
   201	
   202	func saveManifest(path string, grammars []Grammar) error {
   203		var buf bytes.Buffer
   204		enc := json.NewEncoder(&buf)
   205		enc.SetEscapeHTML(false)
   206		enc.SetIndent("", "  ")
   207		if err := enc.Encode(grammars); err != nil {
   208			return err
   209		}
   210		return os.WriteFile(path, buf.Bytes(), 0o644)
   211	}
   212	
   213	// upsert replaces the entry for g.Language, or inserts it, keeping the
   214	// manifest sorted by language.
   215	func upsert(grammars []Grammar, g Grammar) []Grammar {
   216		i := sort.Search(len(grammars), func(i int) bool { return grammars[i].Language >= g.Language })
   217		if i < len(grammars) && grammars[i].Language == g.Language {
   218			grammars[i] = g
   219			return grammars
   220		}
   221		grammars = append(grammars, Grammar{})
   222		copy(grammars[i+1:], grammars[i:])
   223		grammars[i] = g
   224		return grammars
   225	}
